using System.Security.Claims;
using Microsoft.Data.Sqlite;

public static class CoreEndpoints
{
    static string UserId(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.NameIdentifier)!;
    static string Role(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.Role)??"";
    static bool Has(ClaimsPrincipal u,params string[] roles)=>roles.Contains(Role(u));

    public static void MapCoreEndpoints(this WebApplication app)
    {
        app.MapGet("/api/tables",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"""
SELECT t.Id,t.Code,t.Seats,CASE WHEN o.BillRequestedAt IS NOT NULL THEN 'payment_requested' WHEN o.Id IS NOT NULL THEN 'occupied' ELSE t.Status END Status,o.Total,o.OpenedAt,t.PositionX,t.PositionY,t.AreaId,a.Name AreaName,t.Width,t.Height,t.Shape
FROM DiningTables t JOIN Areas a ON a.Id=t.AreaId LEFT JOIN Orders o ON o.Id=(SELECT Id FROM Orders WHERE TableId=t.Id AND Status NOT IN ('paid','cancelled') ORDER BY OpenedAt DESC LIMIT 1) ORDER BY a.Position,t.Code
""");return Results.Ok(rs.Select(r=>new{Id=r.G("Id"),name=r.S("Code"),seats=r.I("Seats"),status=r.S("Status"),total=r["Total"] is null?(int?)null:r.I("Total"),openedAt=r.DN("OpenedAt"),positionX=r.I("PositionX"),positionY=r.I("PositionY"),areaId=r.G("AreaId"),areaName=r.S("AreaName"),width=r.I("Width"),height=r.I("Height"),shape=r.S("Shape")}));});
        app.MapGet("/api/tables/{id:guid}/order",async(Guid id)=>{await using var c=DemoDb.Open();var data=await ReadOrder(c,id.ToString(),true);return data is null?Results.Ok((object?)null):Results.Ok(data);});
        app.MapPost("/api/tables",async(TableInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được thêm bàn."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name)||x.Seats<1)return Results.BadRequest(new{error="Tên bàn và số ghế không hợp lệ."});await using var c=DemoDb.Open();var area=x.AreaId?.ToString()??await DemoDb.ScalarString(c,"SELECT Id FROM Areas ORDER BY Position LIMIT 1");var id=DemoDb.Id();var shape=new[]{"rectangle","round","square"}.Contains(x.Shape)?x.Shape:"rectangle";try{await DemoDb.Exec(c,"INSERT INTO DiningTables(Id,AreaId,Code,Seats,Shape)VALUES(@id,@a,@n,@s,@shape)",( "@id",id),("@a",area),("@n",x.Name.Trim()),("@s",x.Seats),("@shape",shape));return Results.Created($"/api/tables/{id}",new{Id=Guid.Parse(id),name=x.Name.Trim(),seats=x.Seats,status="available"});}catch(SqliteException){return Results.Conflict(new{error="Tên bàn đã tồn tại trong khu vực."});}});

        app.MapGet("/api/products",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Id,Name,BasePrice,IsAvailable FROM Products WHERE IsActive=1 ORDER BY Name");return Results.Ok(rs.Select(r=>new{Id=r.G("Id"),Name=r.S("Name"),price=r.I("BasePrice"),isAvailable=r.B("IsAvailable")}));});
        app.MapPost("/api/products",async(ProductInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền sửa menu."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0)return Results.BadRequest(new{error="Tên và giá sản phẩm không hợp lệ."});await using var c=DemoDb.Open();var category=await DemoDb.ScalarString(c,"SELECT Id FROM Categories ORDER BY Position LIMIT 1");if(category is null){category=DemoDb.Id();var store=await DemoDb.ScalarString(c,"SELECT Id FROM Stores LIMIT 1");await DemoDb.Exec(c,"INSERT INTO Categories(Id,StoreId,Name,Position)VALUES(@id,@s,'Món khác',99)",( "@id",category),("@s",store));}var id=DemoDb.Id();await DemoDb.Exec(c,"INSERT INTO Products(Id,CategoryId,Name,BasePrice,CreatedAt)VALUES(@id,@c,@n,@p,@now)",( "@id",id),("@c",category),("@n",x.Name.Trim()),("@p",x.Price),("@now",DemoDb.Now));return Results.Created($"/api/products/{id}",new{Id=Guid.Parse(id),Name=x.Name.Trim(),price=x.Price});});
        app.MapDelete("/api/products/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền."},statusCode:403);await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE Products SET IsActive=0 WHERE Id=@id",("@id",id))>0?Results.NoContent():Results.NotFound();});
        app.MapPatch("/api/products/{id:guid}/availability",async(Guid id,AvailabilityInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","barista"))return Results.Json(new{error="Bạn không có quyền báo hết món."},statusCode:403);await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE Products SET IsAvailable=@v WHERE Id=@id AND IsActive=1",("@v",x.IsAvailable),("@id",id))>0?Results.Ok(new{id,isAvailable=x.IsAvailable}):Results.NotFound(new{error="Không tìm thấy món."});});

        app.MapPost("/api/orders",async(OrderInput x,ClaimsPrincipal u)=>
        {
            if(!Has(u,"owner","manager","cashier","server"))return Results.Json(new{error="Tài khoản không được tạo đơn."},statusCode:403);if(x.Items.Count==0)return Results.BadRequest(new{error="Đơn hàng chưa có món."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();
            try
            {
                var products=new List<(OrderItemInput Input,string Name,int Price,List<(string Id,string Name,int Price)> Toppings)>();var addedTotal=0;
                foreach(var item in x.Items){if(item.Quantity<1)throw new InvalidOperationException("Số lượng không hợp lệ.");var p=(await DemoDb.Rows(c,tx,"SELECT Name,BasePrice FROM Products WHERE Id=@id AND IsActive=1 AND IsAvailable=1",("@id",item.ProductId))).FirstOrDefault()??throw new InvalidOperationException("Món đã hết hoặc không còn bán.");var tops=new List<(string,string,int)>();foreach(var selected in item.Toppings??[]){var t=(await DemoDb.Rows(c,tx,"SELECT Id,Name,Price FROM ProductToppings WHERE Id=@id AND ProductId=@p AND IsActive=1",("@id",selected.ToppingId),("@p",item.ProductId))).FirstOrDefault()??throw new InvalidOperationException("Topping không hợp lệ.");tops.Add((t.S("Id"),t.S("Name"),t.I("Price")));}addedTotal+=(p.I("BasePrice")+tops.Sum(t=>t.Item3))*item.Quantity;products.Add((item,p.S("Name"),p.I("BasePrice"),tops));}
                var active=(await DemoDb.Rows(c,tx,"SELECT Id,OrderNumber FROM Orders WHERE TableId=@t AND Status NOT IN ('paid','cancelled') ORDER BY OpenedAt DESC LIMIT 1",("@t",x.TableId))).FirstOrDefault();string orderId;long number;
                if(active is null){orderId=DemoDb.Id();number=Convert.ToInt64((await DemoDb.Rows(c,tx,"SELECT COALESCE(MAX(OrderNumber),999)+1 Number FROM Orders")).First().L("Number"));var store=await ScalarTx(c,tx,"SELECT Id FROM Stores LIMIT 1");var shift=await ScalarTx(c,tx,"SELECT Id FROM WorkShifts WHERE OpenedBy=@u AND Status='open' ORDER BY OpenedAt DESC LIMIT 1",("@u",UserId(u)));await DemoDb.Exec(c,tx,"INSERT INTO Orders(Id,StoreId,TableId,OrderNumber,Status,Subtotal,Total,OpenedBy,OpenedAt,ShiftId)VALUES(@id,@s,@t,@no,'sent',@total,@total,@u,@now,@shift)",( "@id",orderId),("@s",store),("@t",x.TableId),("@no",number),("@total",addedTotal),("@u",UserId(u)),("@now",DemoDb.Now),("@shift",shift));}
                else{orderId=active.S("Id");number=active.L("OrderNumber");await DemoDb.Exec(c,tx,"UPDATE Orders SET Subtotal=Subtotal+@v,Total=Subtotal+@v-Discount-LoyaltyDiscount,Status='sent',BillRequestedAt=NULL WHERE Id=@id",("@v",addedTotal),("@id",orderId));}
                foreach(var p in products){var itemId=DemoDb.Id();await DemoDb.Exec(c,tx,"INSERT INTO OrderItems(Id,OrderId,ProductId,ProductName,UnitPrice,Quantity,Note,Status,CreatedAt)VALUES(@id,@o,@p,@n,@price,@qty,@note,'sent',@now)",( "@id",itemId),("@o",orderId),("@p",p.Input.ProductId),("@n",p.Name),("@price",p.Price),("@qty",p.Input.Quantity),("@note",p.Input.Note?.Trim()),("@now",DemoDb.Now));foreach(var t in p.Toppings)await DemoDb.Exec(c,tx,"INSERT INTO OrderItemToppings(Id,OrderItemId,ToppingId,Name,Price)VALUES(@id,@item,@top,@n,@p)",( "@id",DemoDb.Id()),("@item",itemId),("@top",t.Id),("@n",t.Name),("@p",t.Price));}
                await DemoDb.Exec(c,tx,"UPDATE DiningTables SET Status='occupied' WHERE Id=@id",("@id",x.TableId));tx.Commit();return Results.Created($"/api/orders/{orderId}",new{id=Guid.Parse(orderId),orderNumber=number,total=addedTotal});
            }catch(Exception e){tx.Rollback();return Results.BadRequest(new{error=e.Message});}
        });

        app.MapGet("/api/orders/kds",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"""
SELECT o.Id,o.OrderNumber,o.Status,o.OpenedAt,COALESCE(t.Code,'Mang đi') TableName,COALESCE(SUM(CASE WHEN i.Status<>'cancelled' THEN i.Quantity ELSE 0 END),0) ItemCount FROM Orders o LEFT JOIN DiningTables t ON t.Id=o.TableId LEFT JOIN OrderItems i ON i.OrderId=o.Id WHERE o.Status IN ('sent','preparing','ready') GROUP BY o.Id ORDER BY o.OpenedAt
""");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),orderNumber=r.L("OrderNumber"),status=r.S("Status"),openedAt=r.D("OpenedAt"),tableName=r.S("TableName"),itemCount=r.I("ItemCount")}));});
        app.MapGet("/api/orders/{id:guid}",async(Guid id)=>{await using var c=DemoDb.Open();var data=await ReadOrder(c,id.ToString(),false);return data is null?Results.NotFound(new{error="Không tìm thấy đơn hàng."}):Results.Ok(data);});
        app.MapGet("/api/orders",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"""
SELECT o.Id,o.OrderNumber,o.Status,o.Total,o.OpenedAt,o.ClosedAt,COALESCE(t.Code,'Mang đi') TableName,COALESCE(SUM(CASE WHEN i.Status<>'cancelled' THEN i.Quantity ELSE 0 END),0) ItemCount,o.BillRequestedAt,o.OpenedBy FROM Orders o LEFT JOIN DiningTables t ON t.Id=o.TableId LEFT JOIN OrderItems i ON i.OrderId=o.Id GROUP BY o.Id ORDER BY o.OpenedAt DESC
""");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),orderNumber=r.L("OrderNumber"),status=r.S("Status"),total=r.I("Total"),openedAt=r.D("OpenedAt"),closedAt=r.DN("ClosedAt"),tableName=r.S("TableName"),itemCount=r.I("ItemCount"),billRequestedAt=r.DN("BillRequestedAt"),openedBy=string.IsNullOrEmpty(r.S("OpenedBy"))?(Guid?)null:r.G("OpenedBy")}));});
        app.MapPost("/api/orders/{id:guid}/request-bill",async(Guid id,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","server"))return Results.Json(new{error="Chỉ phục vụ hoặc quản lý được gửi yêu cầu in bill."},statusCode:403);await using var c=DemoDb.Open();var now=DemoDb.Now;var changed=await DemoDb.Exec(c,"UPDATE Orders SET BillRequestedAt=COALESCE(BillRequestedAt,@now) WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@now",now),("@id",id));return changed>0?Results.Ok(new{id,billRequestedAt=DateTime.Parse(now),printError=(string?)null}):Results.NotFound(new{error="Đơn không còn hoạt động."});});
        app.MapDelete("/api/order-items/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","cashier","server"))return Results.Json(new{error="Bạn không có quyền hủy món."},statusCode:403);await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var row=(await DemoDb.Rows(c,tx,"SELECT i.OrderId,(i.UnitPrice+COALESCE((SELECT SUM(Price*Quantity) FROM OrderItemToppings WHERE OrderItemId=i.Id),0))*i.Quantity Amount,i.Status FROM OrderItems i WHERE i.Id=@id",("@id",id))).FirstOrDefault();if(row is null){tx.Rollback();return Results.NotFound(new{error="Không tìm thấy món."});}if(row.S("Status")!="sent"){tx.Rollback();return Results.Conflict(new{error="Món đã bắt đầu pha nên không thể hủy."});}var order=row.S("OrderId");var amount=row.I("Amount");await DemoDb.Exec(c,tx,"UPDATE OrderItems SET Status='cancelled' WHERE Id=@id;UPDATE Orders SET Subtotal=MAX(0,Subtotal-@amount),Total=MAX(0,Subtotal-@amount-Discount-LoyaltyDiscount) WHERE Id=@o;INSERT INTO OrderCancellations(Id,OrderId,OrderItemId,CancelledBy,Reason,Amount,CreatedAt)VALUES(@cid,@o,@id,@u,'Hủy trước khi pha',@amount,@now)",( "@id",id),("@amount",amount),("@o",order),("@cid",DemoDb.Id()),("@u",UserId(u)),("@now",DemoDb.Now));if(await ScalarLongTx(c,tx,"SELECT COUNT(*) FROM OrderItems WHERE OrderId=@o AND Status<>'cancelled'",("@o",order))==0){await DemoDb.Exec(c,tx,"UPDATE Orders SET Status='cancelled',ClosedAt=@now WHERE Id=@o;UPDATE DiningTables SET Status='available' WHERE Id=(SELECT TableId FROM Orders WHERE Id=@o)",( "@now",DemoDb.Now),("@o",order));}tx.Commit();return Results.Ok(new{id,status="cancelled",orderId=Guid.Parse(order)});});
        app.MapPatch("/api/order-items/{id:guid}/status",async(Guid id,StatusInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","barista"))return Results.Json(new{error="Chỉ bộ phận pha chế được cập nhật món."},statusCode:403);if(!new[]{"preparing","ready"}.Contains(x.Status))return Results.BadRequest(new{error="Trạng thái không hợp lệ."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var order=(await DemoDb.Command(c,"SELECT OrderId FROM OrderItems WHERE Id=@id",tx,("@id",id)).ExecuteScalarAsync())?.ToString();if(order is null){tx.Rollback();return Results.NotFound(new{error="Không tìm thấy món trong đơn."});}await InventoryEndpoints.DeductItem(c,tx,id.ToString(),UserId(u));await DemoDb.Exec(c,tx,"UPDATE OrderItems SET Status=@s,PreparedBy=COALESCE(PreparedBy,@u),ReadyAt=CASE WHEN @s='ready' THEN @now ELSE ReadyAt END WHERE Id=@id",("@s",x.Status),("@u",UserId(u)),("@now",DemoDb.Now),("@id",id));tx.Commit();await RefreshOrderStatus(c,order);if(x.Status=="ready")await DemoDevices.SendReady(order);return Results.Ok(new{id,status=x.Status,orderId=Guid.Parse(order)});});
        app.MapPatch("/api/orders/{id:guid}/status",async(Guid id,StatusInput x,ClaimsPrincipal u)=>{var allowed=new[]{"sent","preparing","ready","served","paid","cancelled"};if(!allowed.Contains(x.Status))return Results.BadRequest(new{error="Trạng thái không hợp lệ."});if(new[]{"preparing","ready"}.Contains(x.Status)&&!Has(u,"owner","manager","barista")||x.Status=="served"&&!Has(u,"owner","manager","cashier")||new[]{"paid","cancelled"}.Contains(x.Status)&&!Has(u,"owner","manager","cashier"))return Results.Json(new{error="Không có quyền cập nhật trạng thái này."},statusCode:403);await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var row=(await DemoDb.Rows(c,tx,"SELECT TableId,Total,CustomerId,PointsRedeemed FROM Orders WHERE Id=@id",("@id",id))).FirstOrDefault();if(row is null){tx.Rollback();return Results.NotFound();}var closing=new[]{"paid","cancelled"}.Contains(x.Status);if(new[]{"preparing","ready"}.Contains(x.Status))await InventoryEndpoints.DeductOrder(c,tx,id.ToString(),UserId(u));if(x.Status=="cancelled")await InventoryEndpoints.MarkWaste(c,tx,id.ToString());await DemoDb.Exec(c,tx,"UPDATE Orders SET Status=@s,ClosedAt=CASE WHEN @close=1 THEN @now ELSE ClosedAt END,ClosedBy=CASE WHEN @close=1 THEN @u ELSE ClosedBy END WHERE Id=@id;UPDATE OrderItems SET Status=@s,PreparedBy=CASE WHEN @s IN ('preparing','ready') THEN COALESCE(PreparedBy,@u) ELSE PreparedBy END,ReadyAt=CASE WHEN @s='ready' THEN COALESCE(ReadyAt,@now) ELSE ReadyAt END,ServedAt=CASE WHEN @s='served' THEN COALESCE(ServedAt,@now) ELSE ServedAt END WHERE OrderId=@id AND Status NOT IN ('paid','cancelled')",("@s",x.Status),("@close",closing),("@now",DemoDb.Now),("@u",UserId(u)),("@id",id));if(x.Status=="cancelled"){if(!string.IsNullOrEmpty(row.S("CustomerId"))&&row.I("PointsRedeemed")>0)await DemoDb.Exec(c,tx,"UPDATE Customers SET Points=Points+@p WHERE Id=@c",("@p",row.I("PointsRedeemed")),("@c",row.S("CustomerId")));await DemoDb.Exec(c,tx,"INSERT INTO OrderCancellations(Id,OrderId,CancelledBy,Reason,Amount,CreatedAt)VALUES(@cid,@id,@u,@r,@a,@now)",( "@cid",DemoDb.Id()),("@id",id),("@u",UserId(u)),("@r",string.IsNullOrWhiteSpace(x.Reason)?"Hủy toàn bộ đơn":x.Reason.Trim()),("@a",row.I("Total")),("@now",DemoDb.Now));}if(closing&&!string.IsNullOrEmpty(row.S("TableId")))await DemoDb.Exec(c,tx,"UPDATE DiningTables SET Status=CASE WHEN EXISTS(SELECT 1 FROM Orders WHERE TableId=@t AND Status NOT IN ('paid','cancelled') AND Id<>@id) THEN 'occupied' ELSE 'available' END WHERE Id=@t",("@t",row.S("TableId")),("@id",id));tx.Commit();return Results.Ok(new{id,status=x.Status});});

        app.MapGet("/api/reports/summary",async()=>{await using var c=DemoDb.Open();var since=DateTime.UtcNow.AddHours(7).Date.AddHours(-7).ToString("O");var r=(await DemoDb.Rows(c,"SELECT COALESCE(SUM(CASE WHEN Status='paid' THEN Total ELSE 0 END),0) Revenue,SUM(CASE WHEN Status='paid' THEN 1 ELSE 0 END) Paid,SUM(CASE WHEN Status='cancelled' THEN 1 ELSE 0 END) Cancelled FROM Orders WHERE OpenedAt>=@since",("@since",since))).First();return Results.Ok(new{revenue=r.I("Revenue"),paidOrders=r.I("Paid"),cancelledOrders=r.I("Cancelled")});});
        app.MapGet("/api/payment-settings",async()=>{await using var c=DemoDb.Open();var r=(await DemoDb.Rows(c,"SELECT BankId,AccountNumber,AccountName FROM PaymentSettings LIMIT 1")).FirstOrDefault();return Results.Ok(r is null?new{bankId="",accountNumber="",accountName=""}:new{bankId=r.S("BankId"),accountNumber=r.S("AccountNumber"),accountName=r.S("AccountName")});});
        app.MapPut("/api/payment-settings",async(PaymentSettingsInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền cấu hình QR."},statusCode:403);if(string.IsNullOrWhiteSpace(x.BankId)||string.IsNullOrWhiteSpace(x.AccountNumber)||string.IsNullOrWhiteSpace(x.AccountName))return Results.BadRequest(new{error="Vui lòng nhập đủ thông tin tài khoản nhận tiền."});await using var c=DemoDb.Open();var store=await DemoDb.ScalarString(c,"SELECT Id FROM Stores LIMIT 1");await DemoDb.Exec(c,"INSERT INTO PaymentSettings(StoreId,BankId,AccountNumber,AccountName,UpdatedAt)VALUES(@s,@b,@a,@n,@now) ON CONFLICT(StoreId) DO UPDATE SET BankId=excluded.BankId,AccountNumber=excluded.AccountNumber,AccountName=excluded.AccountName,UpdatedAt=excluded.UpdatedAt",("@s",store),("@b",x.BankId.Trim()),("@a",x.AccountNumber.Trim()),("@n",x.AccountName.Trim().ToUpperInvariant()),("@now",DemoDb.Now));return Results.Ok(x);});
        app.MapPost("/api/orders/{id:guid}/pay",async(Guid id,PaymentInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","cashier"))return Results.Json(new{error="Không có quyền thanh toán."},statusCode:403);if(!new[]{"cash","bank_transfer","card","e_wallet"}.Contains(x.Method))return Results.BadRequest(new{error="Phương thức thanh toán không hợp lệ."});await using var c=DemoDb.Open();if(Role(u)=="cashier"&&await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM WorkShifts WHERE OpenedBy=@u AND Status='open'",("@u",UserId(u)))==0)return Results.Conflict(new{error="Thu ngân phải mở ca trước khi nhận thanh toán."});using var tx=c.BeginTransaction();var r=(await DemoDb.Rows(c,tx,"SELECT TableId,Total,CustomerId FROM Orders WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@id",id))).FirstOrDefault();if(r is null){tx.Rollback();return Results.NotFound(new{error="Đơn đã đóng hoặc không tồn tại."});}var shift=await ScalarTx(c,tx,"SELECT Id FROM WorkShifts WHERE OpenedBy=@u AND Status='open' ORDER BY OpenedAt DESC LIMIT 1",("@u",UserId(u)));await DemoDb.Exec(c,tx,"INSERT INTO Payments(Id,OrderId,Amount,Method,Reference,ReceivedBy,PaidAt)VALUES(@pid,@id,@a,@m,@r,@u,@now);UPDATE Orders SET Status='paid',ClosedAt=@now,ClosedBy=@u,ShiftId=@shift WHERE Id=@id;UPDATE OrderItems SET Status='paid' WHERE OrderId=@id AND Status<>'cancelled';UPDATE DiningTables SET Status=CASE WHEN EXISTS(SELECT 1 FROM Orders WHERE TableId=@t AND Status NOT IN ('paid','cancelled') AND Id<>@id) THEN 'occupied' ELSE 'available' END WHERE Id=@t",("@pid",DemoDb.Id()),("@id",id),("@a",r.I("Total")),("@m",x.Method),("@r",x.Reference),("@u",UserId(u)),("@now",DemoDb.Now),("@shift",shift),("@t",r.S("TableId")));if(!string.IsNullOrEmpty(r.S("CustomerId")))await DemoDb.Exec(c,tx,"UPDATE Customers SET TotalSpent=TotalSpent+@a,Points=Points+CAST(@a/10000 AS INTEGER) WHERE Id=@c",("@a",r.I("Total")),("@c",r.S("CustomerId")));tx.Commit();return Results.Ok(new{id,amount=r.I("Total"),earnedPoints=string.IsNullOrEmpty(r.S("CustomerId"))?0:r.I("Total")/10000,method=x.Method,paidAt=DateTime.UtcNow});});
        app.MapGet("/api/users",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Id,FullName,Email,Role,IsActive,CreatedAt FROM Users ORDER BY CreatedAt");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),name=r.S("FullName"),email=r.S("Email"),role=r.S("Role"),isActive=r.B("IsActive"),createdAt=r.D("CreatedAt")}));});
        app.MapPost("/api/users",async(UserInput x)=>{var roles=new[]{"owner","manager","cashier","server","barista"};if(!roles.Contains(x.Role)||string.IsNullOrWhiteSpace(x.Email)||x.Password.Length<8)return Results.BadRequest(new{error="Thông tin nhân viên không hợp lệ."});await using var c=DemoDb.Open();var id=DemoDb.Id();try{await DemoDb.Exec(c,"INSERT INTO Users(Id,StoreId,FullName,Email,PasswordHash,Role,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@n,@e,@p,@r,@now)",( "@id",id),("@n",x.Name.Trim()),("@e",x.Email.Trim().ToLowerInvariant()),("@p",BCrypt.Net.BCrypt.HashPassword(x.Password,12)),("@r",x.Role),("@now",DemoDb.Now));return Results.Ok(new{id=Guid.Parse(id)});}catch(SqliteException){return Results.Conflict(new{error="Email đã tồn tại."});}});
    }

    static async Task<object?> ReadOrder(SqliteConnection c,string id,bool tableId)
    {
        var where=tableId?"o.TableId=@id AND o.Status NOT IN ('paid','cancelled')":"o.Id=@id";var order=(await DemoDb.Rows(c,$"SELECT o.Id,o.OrderNumber,o.Status,o.Total,o.OpenedAt,COALESCE(t.Code,'Mang đi') TableName,o.BillRequestedAt,o.Subtotal,o.Discount,o.LoyaltyDiscount FROM Orders o LEFT JOIN DiningTables t ON t.Id=o.TableId WHERE {where} ORDER BY o.OpenedAt DESC LIMIT 1",("@id",id))).FirstOrDefault();if(order is null)return null;var items=await DemoDb.Rows(c,"SELECT i.Id,i.ProductName,i.UnitPrice+COALESCE((SELECT SUM(Price*Quantity) FROM OrderItemToppings WHERE OrderItemId=i.Id),0) Price,i.Quantity,i.Status,i.Note,i.CreatedAt,(SELECT GROUP_CONCAT(Name,', ') FROM OrderItemToppings WHERE OrderItemId=i.Id) Toppings FROM OrderItems i WHERE i.OrderId=@id ORDER BY i.CreatedAt,i.ProductName",("@id",order.S("Id")));return new{id=order.G("Id"),orderNumber=order.L("OrderNumber"),status=order.S("Status"),total=order.I("Total"),subtotal=order.I("Subtotal"),discount=order.I("Discount"),loyaltyDiscount=order.I("LoyaltyDiscount"),openedAt=order.D("OpenedAt"),tableName=order.S("TableName"),billRequestedAt=order.DN("BillRequestedAt"),items=items.Select(r=>new{id=r.G("Id"),name=r.S("ProductName"),price=r.I("Price"),quantity=r.I("Quantity"),status=r.S("Status"),note=r["Note"]?.ToString(),createdAt=r.D("CreatedAt"),toppings=r["Toppings"]?.ToString()})};
    }
    static async Task RefreshOrderStatus(SqliteConnection c,string order){var waiting=await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM OrderItems WHERE OrderId=@o AND Status NOT IN ('ready','served','cancelled')",("@o",order));var started=await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM OrderItems WHERE OrderId=@o AND Status IN ('preparing','ready','served')",("@o",order));await DemoDb.Exec(c,"UPDATE Orders SET Status=@s WHERE Id=@o",("@s",waiting==0?"ready":started>0?"preparing":"sent"),("@o",order));}
    static async Task<object?> ScalarTx(SqliteConnection c,SqliteTransaction tx,string sql,params(string,object?)[] args)=>await DemoDb.Command(c,sql,tx,args).ExecuteScalarAsync();
    static async Task<long> ScalarLongTx(SqliteConnection c,SqliteTransaction tx,string sql,params(string,object?)[] args)=>Convert.ToInt64(await ScalarTx(c,tx,sql,args)??0);
}

record ProductInput(string Name,int Price);
record TableInput(string Name,int Seats,Guid? AreaId=null,string Shape="rectangle");
record AvailabilityInput(bool IsAvailable);
record OrderInput(Guid TableId,List<OrderItemInput> Items);
record OrderItemInput(Guid ProductId,int Quantity,string? Note,List<ToppingSelectionInput>? Toppings);
record ToppingSelectionInput(Guid ToppingId);
record StatusInput(string Status,string? Reason=null);
record PaymentSettingsInput(string BankId,string AccountNumber,string AccountName);
record PaymentInput(string Method,string? Reference);
record UserInput(string Name,string Email,string Password,string Role);
